CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS kpis (id SERIAL PRIMARY KEY, name VARCHAR(100), value NUMERIC, threshold NUMERIC, status VARCHAR(50)); CREATE TABLE IF NOT EXISTS leads (id SERIAL PRIMARY KEY, phone VARCHAR(50), status VARCHAR(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
